/// <reference path="../.astro/types.d.ts" />
/// <reference path="../worker-configuration.d.ts" />

// `Env` and the `cloudflare:workers` module are generated by `npx wrangler types` into
// worker-configuration.d.ts, straight from the wrangler.jsonc bindings — one source of
// truth, no hand-maintained binding list to drift. Re-run `npm run cf:types` after
// editing wrangler.jsonc.
type CloudflareEnv = Env;

declare namespace App {
  interface Locals {
    // Adapter v14: the ONLY runtime property is `cfContext`. There is deliberately NO
    // `runtime` declared here — `locals.runtime.env` is a getter that THROWS ("removed in
    // Astro v6"). Declaring it makes TypeScript bless code that 500s on every request,
    // which is exactly how that defect passed check + tsc + build during this migration.
    cfContext: ExecutionContext;
    // Per-request CSP nonce (set in src/middleware.ts; consumed by <SeoHead>).
    cspNonce: string;
    // Resolved auth context (null for anonymous public requests).
    session: import('@/lib/auth/types').AuthContext | null;
    // A session that passed the password but still owes its second step (Admin v2 U17): no
    // context, only this. The middleware lets it reach /admin/2fa and sign-out, nothing else.
    secondStep: import('@/lib/auth/twoStep').PendingSecondStep | null;
    // Double-submit CSRF token for admin mutations ('' on public routes).
    csrfToken: string;
    // Request-scoped, cookie-bound Supabase client for /admin and /api/admin. Carries
    // the user's JWT, so every query it makes is subject to RLS — the PRIMARY authz
    // layer. Absent on public routes.
    supabase?: import('@supabase/supabase-js').SupabaseClient;
    // The public identity (`site_profile`), fetched at most once per request — see
    // src/lib/identity/index.ts. A promise, so concurrent components share one fetch.
    identity?: Promise<import('@/lib/identity/fallback').Identity>;
    // Page visibility's snapshot (Admin v2 U14a), read once by the middleware for every
    // public request (src/lib/http/visibility.ts, memoised per isolate): the menus, the
    // sitemap and llms.txt leave out what it does not list. Absent on /admin, /api and the
    // health probe, and in a render with no middleware: read as "every page public".
    visibility?: import('@/lib/http/visibility').VisibilitySnapshot;
    // The studio's time zone (Admin v2 U9, `site_settings.timezone`), read at most once per
    // request by src/lib/admin/studioTimeZone.ts. A promise, as `identity` is.
    studioTimeZone?: Promise<import('@schemas/timeZones').StudioTimeZone>;
    // The public site's icons (Admin v2 U9), read at most once per request by
    // src/lib/data/siteProfile.ts getSiteIcons.
    siteIcons?: Promise<import('@/lib/data/siteProfile').SiteIcons>;
    // The releases preview (Admin v2 R9), set by its middleware branch
    // (src/lib/http/preview.ts) on a `/admin/preview/**` render only: BaseLayout drops the
    // consent banner and telemetry, says noindex and loads the bridge; SectionRenderer marks
    // each section. Absent on every public request.
    preview?: import('@/lib/http/preview').PreviewLocals;
    // Google Analytics 4's measurement id (Admin v2 U15), read once by the middleware before
    // the render, and only while the switch is on, on a public page route answered publicly
    // (src/lib/http/ga4.ts). A promise, so the layout and the CSP share the one answer; null
    // for no id. Absent everywhere else, the preview included: then no loader renders.
    ga4?: Promise<string | null>;
  }
}
